/*
aₘ(f) = f + m where f,m ∈ ℤ 
                    a(g,h) = g+h where g,h ∈ ℝ 
                    b = a(2, 3)
                    a ∈  ℝ -> ℝ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    int b;

    int a(
        const int & m,
        const int & f)
    {
        return f + m;    
    }
    template<typename REAL>
    REAL a(
        const REAL & g,
        const REAL & h)
    {
        return g + h;    
    }
    heartlib(const std::function<double(double)> & a_0)
    {

        // b = a(2, 3)
        b = a(2, 3);
    }
};

