function output = heartlib(a_0)
% output = heartlib(a_0)
%
%    aₘ(f) = f + m where f,m ∈ ℤ 
%                        a(g,h) = g+h where g,h ∈ ℝ 
%                        b = a(2, 3)
%                        a ∈  ℝ -> ℝ
%                        
    % b = a(2, 3)

    b = a(2, 3);
    function [ret_1] = a(m, f)
        assert(numel(m) == 1);
        assert(numel(f) == 1);

        ret_1 = f + m;
    end

    function [ret_2] = a_1(g, h)
        assert(numel(g) == 1);
        assert(numel(h) == 1);

        ret_2 = g + h;
    end

    output.b = b;
    output.a = @a;
    output.a_1 = @a_1;
end

